CREATE TABLE IF NOT EXISTS veasy_orders (id TEXT PRIMARY KEY,shop_id TEXT NOT NULL,order_no TEXT NOT NULL,customer_name TEXT NOT NULL DEFAULT '',customer_phone TEXT NOT NULL DEFAULT '',shipping_address TEXT NOT NULL DEFAULT '',payment_method TEXT NOT NULL DEFAULT 'transfer',payment_status TEXT NOT NULL DEFAULT 'unpaid',fulfillment_status TEXT NOT NULL DEFAULT 'unfulfilled',status TEXT NOT NULL DEFAULT 'pending_payment',total INTEGER NOT NULL DEFAULT 0 CHECK(total>=0),cancellation_token TEXT UNIQUE,cancelled_at TEXT,cancelled_by INTEGER,cancel_reason TEXT NOT NULL DEFAULT '',stock_released_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(shop_id) REFERENCES veasy_shops(id) ON DELETE CASCADE,FOREIGN KEY(cancelled_by) REFERENCES users(id) ON DELETE SET NULL,UNIQUE(shop_id,order_no),CHECK(payment_status IN ('unpaid','review','paid','refunded')),CHECK(fulfillment_status IN ('unfulfilled','packing','shipped','delivered','returned')),CHECK(status IN ('pending_payment','payment_review','cod_pending','paid','packing','shipped','delivered','cancelled')));
CREATE TABLE IF NOT EXISTS veasy_order_items (id TEXT PRIMARY KEY,order_id TEXT NOT NULL,product_id TEXT NOT NULL,product_name TEXT NOT NULL,sku TEXT NOT NULL,unit_price INTEGER NOT NULL CHECK(unit_price>=0),quantity INTEGER NOT NULL CHECK(quantity>0),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(order_id) REFERENCES veasy_orders(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES veasy_products(id) ON DELETE RESTRICT);
CREATE INDEX IF NOT EXISTS idx_veasy_orders_shop ON veasy_orders(shop_id,status,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_veasy_order_items_product ON veasy_order_items(product_id,order_id);
CREATE TABLE IF NOT EXISTS veasy_channels (shop_id TEXT NOT NULL,platform TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'disconnected',external_id TEXT NOT NULL DEFAULT '',updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(shop_id,platform),FOREIGN KEY(shop_id) REFERENCES veasy_shops(id) ON DELETE CASCADE,CHECK(platform IN ('line','facebook')),CHECK(status IN ('connected','disconnected','error')));
CREATE TABLE IF NOT EXISTS veasy_bot_state (shop_id TEXT PRIMARY KEY,state TEXT NOT NULL DEFAULT 'stopped',handoff_platform TEXT NOT NULL DEFAULT '',started_at TEXT,stopped_at TEXT,last_error TEXT NOT NULL DEFAULT '',updated_by INTEGER,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(shop_id) REFERENCES veasy_shops(id) ON DELETE CASCADE,FOREIGN KEY(updated_by) REFERENCES users(id) ON DELETE SET NULL,CHECK(state IN ('stopped','starting','running','human_handoff','error')));
CREATE TABLE IF NOT EXISTS veasy_audit_log (id TEXT PRIMARY KEY,shop_id TEXT NOT NULL,actor_user_id INTEGER,event_type TEXT NOT NULL,entity_type TEXT NOT NULL DEFAULT '',entity_id TEXT NOT NULL DEFAULT '',detail TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(shop_id) REFERENCES veasy_shops(id) ON DELETE CASCADE,FOREIGN KEY(actor_user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE INDEX IF NOT EXISTS idx_veasy_audit_shop ON veasy_audit_log(shop_id,created_at DESC);
